from pathlib import Path

p = Path("/app/handlers.go")
s = p.read_text()

# Fix 1: BOLA in reportsMineHandler - add owner check after row scan
old_reports_mine = """	if owner != cl.Username {
		c.JSON(http.StatusForbidden, gin.H{"error": "Forbidden"})
		return
	}
	report := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}
	if ref > 0 {
		report["escalation_ref"] = ref
	}
	c.JSON(http.StatusOK, gin.H{"report": report})"""
new_reports_mine = """	report := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}
	if ref > 0 {
		report["escalation_ref"] = ref
	}
	c.JSON(http.StatusOK, gin.H{"report": report})"""

# First, try the older pattern if the owner check isn't there yet
if "owner != cl.Username" not in s:
    # No owner check exists yet - it's the original vulnerable version
    # Add owner check to reportsMineHandler
    old_reports_mine_check = """	if err := row.Scan(&id, &owner, &title, &body, &ref); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "No report for this account"})
		return
	}
	report := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}"""
    new_reports_mine_check = """	if err := row.Scan(&id, &owner, &title, &body, &ref); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "No report for this account"})
		return
	}
	if owner != cl.Username && cl.Role != "admin" {
		c.JSON(http.StatusForbidden, gin.H{"error": "Forbidden"})
		return
	}
	report := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}"""
    s = s.replace(old_reports_mine_check, new_reports_mine_check)
    print("handlers.go: added owner check to reportsMineHandler")
else:
    print("handlers.go: reportsMineHandler already has owner check")

# Fix 2: BOLA in reportShowHandler - add owner check
old_report_show = """	if err := row.Scan(&id, &owner, &title, &body, &ref); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "Not found"})
		return
	}
	report := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}
	if ref > 0 {
		report["escalation_ref"] = ref
	}
	c.JSON(http.StatusOK, gin.H{"report": report})"""

if "owner != cl.Username" not in s or "reportShowHandler" not in s[s.find("owner != cl.Username"):s.find("owner != cl.Username")+500]:
    new_report_show = """	if err := row.Scan(&id, &owner, &title, &body, &ref); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "Not found"})
		return
	}
	if owner != cl.Username && cl.Role != "admin" {
		c.JSON(http.StatusForbidden, gin.H{"error": "Forbidden"})
		return
	}
	report := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}
	if ref > 0 {
		report["escalation_ref"] = ref
	}
	c.JSON(http.StatusOK, gin.H{"report": report})"""
    s = s.replace(old_report_show, new_report_show)
    print("handlers.go: added owner check to reportShowHandler")
else:
    print("handlers.go: reportShowHandler already has owner check")

# Fix 3: SQL injection in metersSearchHandler  
old_sqli = """	q := c.Query("q")
	// flag_4 (A03 injection): the user-controlled query is concatenated straight
	// into the SQL string instead of using a bound placeholder.
	query := "SELECT id, label, status FROM meters WHERE label LIKE '%" + q + "%'"
	rows, err := db.Query(query)"""
new_sqli = """	q := c.Query("q")
	query := "SELECT id, label, status FROM meters WHERE label LIKE ?"
	rows, err := db.Query(query, "%"+q+"%")"""

if "bound placeholder" in s:
    s = s.replace(old_sqli, new_sqli)
    print("handlers.go: fixed SQL injection in metersSearchHandler")
else:
    print("handlers.go: SQL injection already fixed")

# Fix 4: Fixed keystream in encryptedExportHandler - use xorWithNonce
old_xor = """	if item == "vault" {
		c.JSON(http.StatusOK, gin.H{"item": item, "cipher_hex": xorWithKeystream(flagValue("flag_3"))})
		return
