old_xor2 = """	c.JSON(http.StatusOK, gin.H{"item": item, "plaintext": content, "cipher_hex": xorWithKeystream(content)})"""
new_xor2 = """	nonce := randomHex(12)
	c.JSON(http.StatusOK, gin.H{"item": item, "plaintext": content, "nonce_hex": nonce, "cipher_hex": xorWithNonce(content, nonce)})"""

if "xorWithNonce(content, nonce)" in s:
    print("handlers.go: meter export already uses xorWithNonce")
else:
    s = s.replace(old_xor2, new_xor2)
    print("handlers.go: meter export now uses xorWithNonce")

p.write_text(s)
print("handlers.go: all patches applied")

