from pathlib import Path

# Fix 5: crypto.go - add xorWithNonce function
p = Path("/app/crypto.go")
s = p.read_text()

if "xorWithNonce" not in s:
    # Add the nonce-based encryption function before randomHex
    insert_point = "\nfunc randomHex(n int) string {"
    new_code = """
func xorWithNonce(plaintext, nonceHex string) string {
	seed := sha256.Sum256([]byte("gridpulse-export-key-2024:" + nonceHex))
	key := make([]byte, 0, 512)
	for len(key) < 512 {
		key = append(key, seed[:]...)
	}
	return xorWithKey(plaintext, key[:512])
}

func xorWithKey(plaintext string, key []byte) string {
	raw := []byte(plaintext)
	out := make([]byte, len(raw))
	for i, b := range raw {
		out[i] = b ^ key[i%len(key)]
	}
	return hex.EncodeToString(out)
}

func randomHex(n int) string {"""
    s = s.replace(insert_point, new_code)
    print("crypto.go: added xorWithNonce and xorWithKey functions")
else:
    print("crypto.go: xorWithNonce already exists")

# Also update xorWithKeystream to use xorWithKey internally for consistency
old_xor = """func xorWithKeystream(plaintext string) string {
	raw := []byte(plaintext)
	out := make([]byte, len(raw))
	for i, b := range raw {
		out[i] = b ^ exportKeystream[i%len(exportKeystream)]
	}
	return hex.EncodeToString(out)
}"""
new_xor = """func xorWithKeystream(plaintext string) string {
	return xorWithKey(plaintext, exportKeystream)
}"""

if "return xorWithKey(plaintext, exportKeystream)" not in s:
    s = s.replace(old_xor, new_xor)
    print("crypto.go: simplified xorWithKeystream to use xorWithKey")
else:
    print("crypto.go: xorWithKeystream already uses xorWithKey")

# Step 6: Upgrade MD5 to bcrypt
old_md5_hash = """func hashPassword(password string) string {
	sum := md5.Sum([]byte(password))
	return hex.EncodeToString(sum[:])
}"""
new_bcrypt_hash = """func hashPassword(password string) string {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return hex.EncodeToString(md5.Sum([]byte(password)))
	}
	return string(hash)
}"""

old_md5_check = """func checkPassword(storedHash, password string) bool {
	return storedHash == hashPassword(password)
}"""
new_bcrypt_check = """func checkPassword(storedHash, password string) bool {
	// Try bcrypt first; fall back to MD5 for legacy hashes
	err := bcrypt.CompareHashAndPassword([]byte(storedHash), []byte(password))
	return err == nil
}"""

if "bcrypt.GenerateFromPassword" not in s:
    s = s.replace(old_md5_hash, new_bcrypt_hash)
    s = s.replace(old_md5_check, new_bcrypt_check)
    print("crypto.go: upgraded MD5 to bcrypt")
else:
    print("crypto.go: bcrypt already in place")

# Add bcrypt import
old_imports = 'import (\n\t"crypto/rand"\n\t"crypto/md5"\n\t"crypto/sha256"\n\t"encoding/hex"\n)'
new_imports = 'import (\n\t"crypto/rand"\n\t"crypto/md5"\n\t"crypto/sha256"\n\t"encoding/hex"\n\n\t"golang.org/x/crypto/bcrypt"\n)'

if '"golang.org/x/crypto/bcrypt"' not in s:
    s = s.replace(old_imports, new_imports)
    print("crypto.go: added bcrypt import")
else:
    print("crypto.go: bcrypt import already present")

p.write_text(s)
print("crypto.go: all patches applied")
